  static function prompts(){
    $data="\n\nAUDIT DATA (verified by our tools – use these facts precisely and do not invent other measurements):\n- Website: {{website}} – overall website score {{web_score}}/100\n- Website category scores: {{web_categories}}\n- Website checks (JSON): {{website_audit}}\n- Google Business Profile score: {{map_score}}/100\n- Google Maps checks (JSON): {{map_audit}}\n- Search phrase analysed: \"{{keyword}}\" – their Google Maps position: #{{position}}\n- Rating {{rating}}★ from {{reviews}} reviews\n- Top competitors on Google Maps (JSON): {{competitors}}\n\nABOUT US: {{agency_name}} ({{agency_website}}). Services: {{services}}.\n";
    $focus="\n\nWHAT TO COVER\n- How customers in {{city}} search for and choose a {{category}}, and where this business is losing them today (Google Maps profile, reviews and reputation, website experience, content, ease of calling / WhatsApp / enquiring, trust signals). Translate every technical issue into what a customer experiences.\n- Real, attributable market statistics relevant to {{category}} and local search (with publisher and year). Estimate monthly searches for \"{{keyword}}\" in {{city}}.\n- A conservative estimate of enquiries today vs. what is achievable in about 6 months, and the typical value of one customer for this kind of business in {{currency}}.\n- Quick wins they can do themselves for free, and a practical 90-day roadmap.\n- Only in how_we_help: how {{agency_name}}'s services fit their gaps. Our yearly package is {{currency_symbol}}{{yearly_fee}}{{fee_note}} – you may mention it once, calmly, in how_we_help.\n\nTONE: a helpful senior consultant giving honest advice. Respectful, specific, encouraging. No hype, no pressure, no fake numbers.";
    $web="Write a growth review for {{business_name}}, a {{category}} business in {{city}} ({{address}}).".$data.str_replace('{{fee_note}}','',$focus);
    $noweb="Write a growth review for {{business_name}}, a {{category}} business in {{city}} ({{address}}). They currently have NO website – explain calmly what a simple, fast website with click-to-call, WhatsApp and service pages would change for their customers, and include a 'Website' finding.".$data.str_replace('{{fee_note}}',' (plus a one-time website of {{currency_symbol}}{{website_fee}})',$focus);
    $wa="Hello {{business_name}} team 👋\n\nThis is {{sender_name}} from {{agency_name}}. We ran a free audit of your Google Maps listing and website, and found a few things that may be costing you customer enquiries.\n\nI have attached your personalised report (PDF) – please have a look, it takes just 2 minutes.\n\nShall I explain the key points on a quick call?";
    $wan="Hello {{business_name}} team 👋\n\nThis is {{sender_name}} from {{agency_name}}. We checked your Google Maps listing and noticed you don't have a website yet – many customers search on Google before calling.\n\nI have attached a free Google Maps audit report and a short website proposal (PDF). Please have a look.\n\nShall I explain it on a quick call?";
    $em="Hi {{business_name}} team,\n\nI'm {{sender_name}} from {{agency_name}}. We ran a free audit of your website ({{website}}) and your Google Maps listing, and found a few quick wins that can help you get more enquiries from Google.\n\nYour personalised report is attached as a PDF.\n\nIf you'd like, I can walk you through it in a short 15-minute call – just reply to this email.\n\nBest regards,\n{{sender_name}}\n{{agency_name}}\n{{agency_phone}} | {{agency_website}}";
    $emn="Hi {{business_name}} team,\n\nI'm {{sender_name}} from {{agency_name}}. While checking businesses on Google Maps for \"{{keyword}}\", we noticed you don't have a website yet.\n\nI've attached a free Google Maps audit report and a short website proposal.\n\nIf you'd like, I can walk you through it in a short 15-minute call – just reply to this email.\n\nBest regards,\n{{sender_name}}\n{{agency_name}}\n{{agency_phone}} | {{agency_website}}";
    return [
      ['report_website','Growth review v3 – website & Maps','',$web],
      ['report_noweb','Growth review v3 – Maps + website plan','',$noweb],
      ['whatsapp','Default – WhatsApp first message','',$wa],
      ['whatsapp_noweb','Default – WhatsApp (no website)','',$wan],
      ['email','Default – Email first message','Free audit: how {{business_name}} can get more customers from Google',$em],
      ['email_noweb','Default – Email (no website)','{{business_name}}: free Google Maps audit & website idea',$emn]];}
  static function types(){return ['report_website'=>['Report · has website','AI prompt that writes the PDF audit when the business has a website.'],'report_noweb'=>['Report · no website','AI prompt for businesses without a website (Maps audit + website proposal).'],'whatsapp'=>['WhatsApp','First WhatsApp message, sent with the PDF attached. Keep it simple – no fees.'],'whatsapp_noweb'=>['WhatsApp · no website','First WhatsApp message for businesses without a website.'],'email'=>['Email','First email, sent with the PDF attached.'],'email_noweb'=>['Email · no website','First email for businesses without a website (proposal PDF attached).']];}
  static function fields(){return [['business_type','Business type','select',"Retail\nClinic / Healthcare\nRestaurant / Café\nReal estate\nEducation\nProfessional services\nManufacturing\nOther"],['budget','Monthly budget','number',''],['requirement','Requirement','textarea',''],['preferred_time','Preferred contact time','select',"Morning\nAfternoon\nEvening"]];}
  static function upgradeReports(){
    foreach(self::prompts() as [$t,$n,$s,$c]){
      if(strpos($t,'report_')!==0||DB::val('SELECT id FROM prompts WHERE type=? AND name=?',[$t,$n]))continue;
      $id=DB::insert('prompts',['type'=>$t,'name'=>$n,'subject'=>$s,'content'=>$c,'is_default'=>1]);
      DB::q('UPDATE prompts SET is_active=(id=?) WHERE type=?',[$id,$t]);}}
  static function defaults(){
    $have=array_column(DB::all('SELECT k FROM settings'),'k');
    foreach(self::settings() as $k=>$v)if(!in_array($k,$have,true))Settings::set($k,$v);
    $types=array_column(DB::all('SELECT DISTINCT type FROM prompts'),'type');
    foreach(self::prompts() as [$t,$n,$s,$c])if(!in_array($t,$types,true))DB::insert('prompts',['type'=>$t,'name'=>$n,'subject'=>$s,'content'=>$c,'is_active'=>1,'is_default'=>1]);
    if(!DB::val('SELECT COUNT(*) FROM fields'))foreach(self::fields() as $i=>[$k,$l,$ty,$o])DB::insert('fields',['fkey'=>$k,'label'=>$l,'type'=>$ty,'options'=>$o,'sort'=>$i]);}}
